// Service worker for the web release (GitHub Pages). Registered only on
// http(s) by js/sw-register.js, so the desktop app:// build ignores it.
//
// Strategy:
//   - Precache (self.PRECACHE, from sw-assets.js — generated by
//     tools/make_web_release.js): everything the app needs to start:
//     HTML/CSS/JS/data/fonts/UI plus the question figures. Entries are
//     [url, fingerprint] pairs; the fingerprint is a content hash (see
//     sw-assets.js header), so the cache version tracks content edits.
//   - assets/source_rows/*.png (row screenshots, ~31 MB): NOT precached.
//     Fetched on first use, then served from cache — keeps the install
//     light and offline still covers everything the app can show.
//   - Navigations: network first, fall back to cache when offline.
//   - Everything else: cache first, fill the cache from the network.
//   - Bypass: fonts.googleapis.com (Google's own CDN handles its caching).

importScripts('sw-assets.js'); // defines self.PRECACHE

// Version derived from the precache list itself: every [url, fingerprint]
// pair is folded in, so adding, removing OR re-contenting any precached file
// bumps it, which forces every installed app to refresh its cache.
let VERSION = 0;
for (const [entry, hash] of PRECACHE) {
  const key = entry + ':' + hash;
  for (let i = 0; i < key.length; i++) VERSION = (VERSION * 33 + key.charCodeAt(i)) | 0;
}
const CACHE = `quiz-nautica-v${VERSION}`;

let clientReady = false;
self.addEventListener('install', (event) => {
  clientReady = true; // the page that installed this worker is still open
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map(([url]) => url))));
});

// A waiting worker only takes over when the tab is hidden (e.g. "Add to
// Home Screen" closes it). When the tab is still open, we must hand the
// page to the new worker immediately, otherwise the first launch after
// the app updated would stay on the stale code until a manual reload.
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys()) {
        if (name !== CACHE && name.startsWith('quiz-nautica-')) await caches.delete(name);
      }
      const clients = await self.clients.matchAll({ type: 'window' });
      if (clientReady || clients.length === 0) await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  // Google Fonts' css2 endpoint: serve straight from network, never cache.
  if (request.url.startsWith('https://fonts.googleapis.com/')) return;

  // App navigations (opening the app / refreshing it): try the network
  // first so updates show up, fall back to the cached app when offline.
  if (request.mode === 'navigate' || request.url === self.url.origin + '/') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(() =>
          caches.match(request).then((cached) => cached || caches.match('./index.html'))
        )
    );
    return;
  }

  // Static app assets (css, js, data, images, fonts): cache first, then
  // network, storing anything new so it works offline from next time on.
  event.respondWith(
    caches.match(request).then(
      (cached) =>
        cached ||
        fetch(request).then((response) => {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
          return response;
        })
    )
  );
});
